package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextToken().
 * Focuses on maximizing branch and line coverage.
 */
public class ReaderBasedJsonParser_nextToken_TriageGen0Test {

    private ReaderBasedJsonParser createParser(String content) throws IOException {
        // Using the public constructor available in the prompt
        // Note: In a real Jackson environment, we'd use JsonFactory to get this.
        // Since we are testing the class directly, we simulate the minimal required context.
        return new ReaderBasedJsonParser(
                IOContext.bootstrap(),
                0,
                new StringReader(content),
                null,
                null
        );
    }

    @Test
    public void testNextToken_EndofInput() throws IOException {
        ReaderBasedJsonParser parser = createParser("");
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_SimpleValue_True() throws IOException {
        ReaderBasedJsonParser parser = createParser("true");
        assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_SimpleValue_False() throws IOException {
        ReaderBasedJsonParser parser = createParser("false");
        assertEquals(JsonToken.VALUE_FALSE, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_SimpleValue_Null() throws IOException {
        ReaderBasedJsonParser parser = createParser("null");
        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_PositiveNumber() throws IOException {
        ReaderBasedJsonParser parser = createParser("123");
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextToken_NegativeNumber() throws IOException {
        ReaderBasedJsonParser parser = createParser("-123");
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextToken_String() throws IOException {
        ReaderBasedJsonParser parser = createParser("\"hello\"");
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextToken_StartArray() throws IOException {
        ReaderBasedJsonParser parser = createParser("[");
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
    }

    @Test
    public void testNextToken_StartObject() throws IOException {
        ReaderBasedJsonParser parser = createParser("{");
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextToken_EndArray() throws IOException {
        ReaderBasedJsonParser parser = createParser("[]");
        parser.nextToken(); // START_ARRAY
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    @Test
    public void testNextToken_EndObject() throws IOException {
        ReaderBasedJsonParser parser = createParser("{}");
        parser.nextToken(); // START_OBJECT
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextToken_ObjectWithFields() throws IOException {
        // Tests: inObject logic, FIELD_NAME, skipColon, and field name + value combined return
        ReaderBasedJsonParser parser = createParser("{\"key\": \"value\"}");

        // 1. START_OBJECT
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // 2. FIELD_NAME (The code returns _nextAfterName() when current is FIELD_NAME)
        // In the logic: if (inObject) { _currToken = FIELD_NAME; i = skipColon(); ... _nextToken = t; return _currToken; }
        // Actually, the first call to nextToken in an object context will return FIELD_NAME.
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("key", parser.getCurrentName());

        // 3. VALUE_STRING (The next token after FIELD_NAME triggers _nextAfterName which returns the value)
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        // 4. END_OBJECT
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextToken_ArrayWithComma() throws IOException {
        ReaderBasedJsonParser parser = createParser("[1, 2]");
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    @Test(expected = IOException.class)
    public void testNextToken_MismatchedEndArray() throws IOException {
        // Testing: if (i == INT_RBRACKET) { if (!_parsingContext.inArray()) { _reportMismatchedEndMarker(i, '}'); } }
        ReaderBasedJsonParser parser = createParser("}");
        parser.nextToken();
    }

    @Test(expected = IOException.class)
    public void testNextToken_MismatchedEndObject() throws IOException {
        // Testing: if (i == INT_RCURLY) { if (!_parsingContext.inObject()) { _reportMismatchedEndMarker(i, ']'); } }
        ReaderBasedJsonParser parser = createParser("]");
        parser.nextToken();
    }

    @Test(expected = IOException.class)
    public void testNextToken_UnexpectedChar() throws IOException {
        // Testing the default/error case: case ']': case '}': _reportUnexpectedChar
        ReaderBasedJsonParser parser = createParser("]"); 
        // If we are at root, ']' is handled by the end-of-input or the mismatch check.
        // To hit the 'default' or the specific ']' case in the switch:
        // We need to be in a context where ']' is not a valid closer for the current level.
        // However, the logic for ']' at root is handled by the i < 0 or the i == INT_RBRACKET.
        // Let's try a character that falls into _handleOddValue.
        ReaderBasedJsonParser parser2 = createParser("?");
        parser2.nextToken();
    }

    @Test
    public void testNextToken_IncompleteStringHandling() throws IOException {
        // Tests: if (_tokenIncomplete) { _skipString(); }
        // This usually happens when a previous token was a string that wasn't closed properly
        // or if the parser state was manually manipulated.
        // Since we are using a standard constructor, we simulate by providing a broken string.
        ReaderBasedJsonParser parser = createParser("\"unfinished");
        // This will likely throw an exception during parsing, but tests the code path
        try {
            parser.nextToken();
        } catch (Exception e) {
            // Expected
        }
    }
}
